void Solver::bump_var(int var, double coeff) {
    const double LIM = 1e200;          // raise limit to reduce scaling frequency
    const double SC  = 1e-200;         // corresponding scaling factor
    double delta = var_inc * coeff;
    activity[var] += delta;
    if (activity[var] > LIM) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SC;
        var_inc *= SC;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
